def pick_background_image(generated_at: str, run_type: str) -> str:
    """Ã¥Â®ÂÃ¨Â¡ÂÃ¦ÂÂ¥(YYYY-MM-DD)Ã£ÂÂ¨Ã¦ÂÂ/Ã¥Â¤ÂÃ£ÂÂ®Ã¥ÂÂºÃ¥ÂÂÃ£ÂÂÃ£ÂÂÃ¨ÂÂÃ¦ÂÂ¯Ã¥ÂÂÃ§ÂÂÃ£ÂÂÃ¦Â±ÂºÃ¥Â®ÂÃ£ÂÂÃ£ÂÂÃ£ÂÂ
    Ã¥ÂÂÃ£ÂÂÃ¦ÂÂ¥Ã£ÂÂ§Ã£ÂÂÃ¦ÂÂÃ£ÂÂ¨Ã¥Â¤ÂÃ£ÂÂ§Ã©ÂÂÃ£ÂÂÃ¥ÂÂÃ§ÂÂÃ£ÂÂ«Ã£ÂÂªÃ£ÂÂÃ£ÂÂÃ¦ÂÂ¥Ã£ÂÂÃ¥Â¤ÂÃ£ÂÂÃ£ÂÂÃ£ÂÂ¨Ã£ÂÂ­Ã£ÂÂ¼Ã£ÂÂÃ£ÂÂ¼Ã£ÂÂ·Ã£ÂÂ§Ã£ÂÂ³Ã£ÂÂÃ©ÂÂ²Ã£ÂÂÃ£ÂÂ"""
    urls = [u for u, _ in BACKGROUND_IMAGES]
    try:
        day_ordinal = datetime.strptime(generated_at[:10], "%Y-%m-%d").toordinal()
    except (ValueError, TypeError):
        day_ordinal = datetime.now().toordinal()
    slot = 0 if run_type == "morning" else 1
    idx = (day_ordinal * 2 + slot) % len(urls)
    return urls[idx]

def esc(x):
    if x is None:
        return ""
    return html_lib.escape(str(x))


def fmt_pct(v):
    try:
        v = float(v)
    except (TypeError, ValueError):
        return "Ã¢ÂÂ"
    sign = "+" if v > 0 else ""
    return f"{sign}{v:.2f}%"


def pct_class(v):
    try:
        v = float(v)
    except (TypeError, ValueError):
        return "flat"
    if v > 0:
        return "up"
    if v < 0:
        return "down"
    return "flat"


def mini_bar_html(value, scale=8.0):
    """Ã¥ÂÂÃ¦ÂÂ¥Ã¦Â¯ÂÃ£ÂÂªÃ£ÂÂ©Ã£ÂÂ®Ã¦ÂÂ°Ã¥ÂÂ¤Ã£ÂÂÃ£ÂÂÃ¤Â¸Â­Ã¥Â¿ÂÃ£ÂÂÃ£ÂÂÃ¥Â·Â¦Ã¥ÂÂ³Ã£ÂÂ«Ã¤Â¼Â¸Ã£ÂÂ³Ã£ÂÂÃ£ÂÂÃ£ÂÂ diverging bar Ã£ÂÂ¨Ã£ÂÂÃ£ÂÂ¦Ã¥ÂÂ¯Ã¨Â¦ÂÃ¥ÂÂÃ£ÂÂÃ£ÂÂÃ£ÂÂ
    Ã§ÂÂÃ£ÂÂ®Ã£ÂÂ­Ã£ÂÂ¼Ã£ÂÂ½Ã£ÂÂ¯Ã¨Â¶Â³Ã£ÂÂÃ£ÂÂ£Ã£ÂÂ¼Ã£ÂÂÃ£ÂÂ«Ã£ÂÂ¯Ã¦ÂÂÃ§Â³Â»Ã¥ÂÂOHLCÃ£ÂÂÃ£ÂÂ¼Ã£ÂÂ¿Ã£ÂÂÃ¥Â¿ÂÃ¨Â¦ÂÃ£ÂÂ§data.jsonÃ£ÂÂ«Ã£ÂÂ¯Ã¥ÂÂ«Ã£ÂÂ¾Ã£ÂÂÃ£ÂÂªÃ£ÂÂÃ£ÂÂÃ£ÂÂÃ£ÂÂ
    Ã¦ÂÂ¢Ã¥Â­ÂÃ£ÂÂ®Ã¦ÂÂ°Ã¥ÂÂ¤(Ã¥ÂÂÃ¦ÂÂ¥Ã¦Â¯Â%Ã£ÂÂªÃ£ÂÂ©)Ã£ÂÂÃ¨Â¦ÂÃ¨Â¦ÂÃ§ÂÂÃ£ÂÂ«Ã¦ÂÂÃ¦ÂÂ¡Ã£ÂÂÃ£ÂÂÃ£ÂÂÃ£ÂÂÃ£ÂÂÃ£ÂÂÃ§Â°Â¡Ã¦ÂÂÃ£ÂÂÃ£ÂÂÃ£ÂÂ°Ã£ÂÂ©Ã£ÂÂÃ£ÂÂ¨Ã£ÂÂÃ£ÂÂ¦Ã¦ÂÂÃ¤Â¾ÂÃ£ÂÂÃ£ÂÂÃ£ÂÂ"""
    try:
        v = float(value)
    except (TypeError, ValueError):
        return ""
    cls = pct_class(v)
    if cls == "flat":
        return '<span class="mini-bar" aria-hidden="true"></span>'
    magnitude = min(abs(v), scale) / scale * 50.0
    side = "right" if v > 0 else "left"
    return (
        f'<span class="mini-bar" aria-hidden="true">'
        f'<span class="mini-bar-fill {cls}" style="{side}:50%; width:{magnitude:.1f}%;"></span>'
        f'</span>'
    )


def rsi_gauge_html(rsi):
    """RSI(14)Ã£ÂÂ0-100Ã£ÂÂ®Ã¥Â¸Â¯Ã£ÂÂ°Ã£ÂÂ©Ã£ÂÂ+Ã£ÂÂÃ£ÂÂ¼Ã£ÂÂ«Ã£ÂÂ¼Ã£ÂÂ§Ã¥ÂÂ¯Ã¨Â¦ÂÃ¥ÂÂÃ£ÂÂÃ£ÂÂÃ§Â°Â¡Ã¦ÂÂÃ£ÂÂ²Ã£ÂÂ¼Ã£ÂÂ¸Ã£ÂÂ"""
    try:
        v = float(rsi)
    except (TypeError, ValueError):
        return esc(rsi)
    v_clamped = max(0.0, min(100.0, v))
    zone = "warn-hot" if v >= 70 else ("warn-cold" if v <= 30 else "normal")
    return (
        f'<span class="rsi-gauge">'
        f'<span class="rsi-gauge-track">'
        f'<span class="rsi-gauge-marker {zone}" style="left:{v_clamped:.1f}%;"></span>'
        f'</span>'
        f'<span class="rsi-gauge-num">{v:.1f}</span>'
        f'</span>'
    )


def code_link(code):
    """Ã©ÂÂÃ¦ÂÂÃ£ÂÂ³Ã£ÂÂ¼Ã£ÂÂÃ£ÂÂYahoo!Ã£ÂÂÃ£ÂÂ¡Ã£ÂÂ¤Ã£ÂÂÃ£ÂÂ³Ã£ÂÂ¹Ã£ÂÂ®Ã¨Â©Â²Ã¥Â½ÂÃ£ÂÂÃ£ÂÂ¼Ã£ÂÂ¸Ã£ÂÂ¸Ã£ÂÂ®Ã£ÂÂªÃ£ÂÂ³Ã£ÂÂ¯Ã£ÂÂ«Ã£ÂÂÃ£ÂÂ(4Ã¦Â¡ÂÃ¥ÂÂÃ¥Â¾ÂÃ£ÂÂ®Ã¨Â¨Â¼Ã¥ÂÂ¸Ã£ÂÂ³Ã£ÂÂ¼Ã£ÂÂÃ£ÂÂ®Ã£ÂÂ¿)Ã£ÂÂ"""
    c = (code or "").strip()
    if not c:
        return ""
    if re.match(r"^\d{3,5}[A-Z]?$", c):
        return f'<a href="https://finance.yahoo.co.jp/quote/{esc(c)}.T" target="_blank" rel="noopener">{esc(c)}</a>'
    return esc(c)


