def parse_signal_counts(summary):
    """summaryÃ¦ÂÂÃ¥Â­ÂÃ¥ÂÂÃ£ÂÂÃ£ÂÂÃ£ÂÂÃ¤Â¸Â­Ã§Â«ÂX/Ã¥Â£Â²Ã£ÂÂY/Ã¨Â²Â·Ã£ÂÂZÃ£ÂÂÃ£ÂÂ¾Ã£ÂÂÃ£ÂÂ¯Ã£ÂÂÃ¥Â£Â²Ã£ÂÂY/Ã¤Â¸Â­Ã§Â«ÂX/Ã¨Â²Â·Ã£ÂÂZÃ£ÂÂÃ¥Â½Â¢Ã¥Â¼ÂÃ£ÂÂ®Ã£ÂÂ·Ã£ÂÂ°Ã£ÂÂÃ£ÂÂ«Ã¥ÂÂÃ¨Â¨Â³Ã£ÂÂÃ¦ÂÂ½Ã¥ÂÂºÃ£ÂÂÃ¨Â¦ÂÃ£ÂÂ¤Ã£ÂÂÃ£ÂÂÃ£ÂÂªÃ£ÂÂÃ£ÂÂÃ£ÂÂ°NoneÃ£ÂÂ"""
    if not summary:
        return None
    # Ã¥Â½Â¢Ã¥Â¼Â1: Ã¥Â£Â²Ã£ÂÂN/Ã¤Â¸Â­Ã§Â«ÂN/Ã¨Â²Â·Ã£ÂÂN (Ã¦ÂÂ°Ã£ÂÂÃ£ÂÂ©Ã£ÂÂ¼Ã£ÂÂÃ£ÂÂÃ£ÂÂ)
    m = re.search(r"Ã¥Â£Â²Ã£ÂÂ\s*(\d+)\s*/\s*Ã¤Â¸Â­Ã§Â«Â\s*(\d+)\s*/\s*Ã¨Â²Â·Ã£ÂÂ\s*(\d+)", summary)
    if m:
        sell, neutral, buy = (int(x) for x in m.groups())
        return {"neutral": neutral, "sell": sell, "buy": buy}
    # Ã¥Â½Â¢Ã¥Â¼Â2: Ã¤Â¸Â­Ã§Â«ÂN/Ã¥Â£Â²Ã£ÂÂN/Ã¨Â²Â·Ã£ÂÂN (Ã¦ÂÂ§Ã£ÂÂÃ£ÂÂ©Ã£ÂÂ¼Ã£ÂÂÃ£ÂÂÃ£ÂÂ)
    m = re.search(r"Ã¤Â¸Â­Ã§Â«Â\s*(\d+)\s*/\s*Ã¥Â£Â²Ã£ÂÂ\s*(\d+)\s*/\s*Ã¨Â²Â·Ã£ÂÂ\s*(\d+)", summary)
    if m:
        neutral, sell, buy = (int(x) for x in m.groups())
        return {"neutral": neutral, "sell": sell, "buy": buy}
    return None
def rank_label(i):
    medals = ["Ã°ÂÂ¥Â", "Ã°ÂÂ¥Â", "Ã°ÂÂ¥Â"]
    return medals[i] if i < len(medals) else f"{i + 1}Ã¤Â½Â"


def bull_ranking_html(items, empty_msg="Ã£ÂÂ·Ã£ÂÂ°Ã£ÂÂÃ£ÂÂ«Ã£ÂÂÃ£ÂÂ¼Ã£ÂÂ¿Ã£ÂÂÃ¥ÂÂÃ¥Â¾ÂÃ£ÂÂ§Ã£ÂÂÃ£ÂÂ¾Ã£ÂÂÃ£ÂÂÃ£ÂÂ§Ã£ÂÂÃ£ÂÂÃ£ÂÂ"):
    """Ã£ÂÂÃ£ÂÂ¯Ã£ÂÂÃ£ÂÂ«Ã£ÂÂ«Ã¦ÂÂÃ¦Â¨ÂÃ£ÂÂ®Ã£ÂÂÃ¨Â²Â·Ã£ÂÂÃ£ÂÂ·Ã£ÂÂ°Ã£ÂÂÃ£ÂÂ«Ã¦ÂÂ°Ã£ÂÂÃ£ÂÂÃ¨Â»Â¸Ã£ÂÂ«Ã£ÂÂÃ£ÂÂÃ£ÂÂÃ©ÂÂÃ¥ÂÂ»Ã£ÂÂÃ£ÂÂ¼Ã£ÂÂ¿Ã£ÂÂÃ£ÂÂ¼Ã£ÂÂ¹Ã£ÂÂ®Ã¦Â©ÂÃ¦Â¢Â°Ã§ÂÂÃ£ÂÂ©Ã£ÂÂ³Ã£ÂÂ­Ã£ÂÂ³Ã£ÂÂ°Ã£ÂÂ
    Ã¥Â°ÂÃ¦ÂÂ¥Ã£ÂÂ®Ã¦Â ÂªÃ¤Â¾Â¡Ã¤Â¸ÂÃ¦ÂÂÃ£ÂÂÃ¤ÂºÂÃ¦ÂÂ³Ã£ÂÂ»Ã¤Â¿ÂÃ¨Â¨Â¼Ã£ÂÂÃ£ÂÂÃ£ÂÂÃ£ÂÂ®Ã£ÂÂ§Ã£ÂÂ¯Ã£ÂÂªÃ£ÂÂÃ£ÂÂ"""
    ranked = []
    for it in items:
        counts = parse_signal_counts(it.get("summary", ""))
        if not counts:
            continue
        score = counts["buy"] * 2 - counts["sell"]
        ranked.append((score, counts, it))
    if not ranked:
        return f'<p class="empty">{esc(empty_msg)}</p>'

    def rsi_key(entry):
        try:
            return float(entry[2].get("rsi", 50))
        except (TypeError, ValueError):
            return 50.0

    ranked.sort(key=lambda e: (-e[0], rsi_key(e)))

    def build_rows(group):
        rows = []
        for i, (score, counts, it) in enumerate(group[:5]):
            code = esc(it.get("code", ""))
            name = esc(it.get("name", ""))
            chg = it.get("change_pct")
            rsi = it.get("rsi", "")
            detail = f"Ã¤Â¸Â­Ã§Â«Â{counts['neutral']}/Ã¥Â£Â²Ã£ÂÂ{counts['sell']}/Ã¨Â²Â·Ã£ÂÂ{counts['buy']}"
            overheat = ""
            try:
                if float(rsi) >= 70:
                    overheat = ' <span class="tag tag-warn">Ã©ÂÂÃ§ÂÂ±Ã¦ÂÂÃ£ÂÂ«Ã¦Â³Â¨Ã¦ÂÂ</span>'
            except (TypeError, ValueError):
                pass
            rows.append(f"""
        <div class="rank-item">
          <div class="rank-num">{rank_label(i)}</div>
          <div class="rank-body">
            <div class="rank-head">
              <span class="mono">{code}</span> {name}
              <span class="mono {pct_class(chg)}">{fmt_pct(chg)}</span>
              <span class="score-tag">Ã¥Â¼Â·Ã¦Â°ÂÃ£ÂÂ¹Ã£ÂÂ³Ã£ÂÂ¢ {score:+d}</span>
            </div>
            <div class="rank-desc">Ã£ÂÂ·Ã£ÂÂ°Ã£ÂÂÃ£ÂÂ«Ã¥ÂÂ¤Ã¥Â®Â: {esc(detail)} Ã£ÂÂ» RSI(14) {esc(rsi)}{overheat}</div>
          </div>
        </div>""")
        return rows

    bull_items = sorted([(s, c, it) for s, c, it in ranked if s > 0], key=lambda e: (-e[0], rsi_key(e)))
    bear_items = sorted([(s, c, it) for s, c, it in ranked if s < 0], key=lambda e: (e[0], rsi_key(e)))

    html_parts = []
    html_parts.append('<h4 style="margin:0.5em 0 0.4em;color:var(--up)">Ã°ÂÂÂ¢ Ã¥Â¼Â·Ã¦Â°ÂÃ¯Â¼ÂÃ¨Â²Â·Ã£ÂÂÃ£ÂÂ·Ã£ÂÂ°Ã£ÂÂÃ£ÂÂ«Ã¥ÂÂªÃ¥ÂÂ¢Ã¯Â¼Â</h4>')
    if bull_items:
        html_parts.extend(build_rows(bull_items))
    else:
        html_parts.append('<p class="empty">Ã§ÂÂ¾Ã¥ÂÂ¨Ã£ÂÂÃ¨Â²Â·Ã£ÂÂÃ£ÂÂ·Ã£ÂÂ°Ã£ÂÂÃ£ÂÂ«Ã¥ÂÂªÃ¥ÂÂ¢Ã£ÂÂ®Ã©ÂÂÃ¦ÂÂÃ£ÂÂ¯Ã£ÂÂÃ£ÂÂÃ£ÂÂ¾Ã£ÂÂÃ£ÂÂÃ£ÂÂ</p>')
    html_parts.append('<h4 style="margin:1.2em 0 0.4em;color:var(--down)">Ã°ÂÂÂ´ Ã¥Â¼Â±Ã¦Â°ÂÃ¯Â¼ÂÃ¥Â£Â²Ã£ÂÂÃ£ÂÂ·Ã£ÂÂ°Ã£ÂÂÃ£ÂÂ«Ã¥ÂÂªÃ¥ÂÂ¢Ã¯Â¼Â</h4>')
    if bear_items:
        html_parts.extend(build_rows(bear_items))
    else:
        html_parts.append('<p class="empty">Ã§ÂÂ¾Ã¥ÂÂ¨Ã£ÂÂÃ¥Â£Â²Ã£ÂÂÃ£ÂÂ·Ã£ÂÂ°Ã£ÂÂÃ£ÂÂ«Ã¥ÂÂªÃ¥ÂÂ¢Ã£ÂÂ®Ã©ÂÂÃ¦ÂÂÃ£ÂÂ¯Ã£ÂÂÃ£ÂÂÃ£ÂÂ¾Ã£ÂÂÃ£ÂÂÃ£ÂÂ</p>')
    return "".join(html_parts)


def _technical_lookup(technical):
    """code -> technicalÃ¦ÂÂÃ¦Â¨Âdict Ã£ÂÂ®Ã£ÂÂ«Ã£ÂÂÃ£ÂÂ¯Ã£ÂÂ¢Ã£ÂÂÃ£ÂÂÃ£ÂÂÃ£ÂÂ¼Ã£ÂÂÃ£ÂÂ«Ã£ÂÂÃ¤Â½ÂÃ£ÂÂÃ£ÂÂ"""
    lookup = {}
    for t in technical or []:
        code = str(t.get("code", "")).strip()
        if code:
            lookup[code] = t
    return lookup


def _outlook_comment(code, tech_lookup):
    """Ã§ÂÂ´Ã¨Â¿ÂÃ£ÂÂ®Ã£ÂÂÃ£ÂÂ¯Ã£ÂÂÃ£ÂÂ«Ã£ÂÂ«Ã¦ÂÂÃ¦Â¨Â(RSIÃ£ÂÂ»Ã§Â§Â»Ã¥ÂÂÃ¥Â¹Â³Ã¥ÂÂÃ¤Â¹ÂÃ©ÂÂ¢Ã£ÂÂ»Ã£ÂÂ·Ã£ÂÂ°Ã£ÂÂÃ£ÂÂ«Ã¥ÂÂ¤Ã¥Â®Â)Ã£ÂÂÃ£ÂÂÃ£ÂÂÃ£ÂÂÃ£ÂÂ®Ã©ÂÂÃ¦ÂÂÃ£ÂÂ«Ã£ÂÂ¤Ã£ÂÂÃ£ÂÂ¦
    Ã§Â«Â¯Ã§ÂÂÃ£ÂÂªÃ¥ÂÂÃ¨ÂÂÃ£ÂÂ³Ã£ÂÂ¡Ã£ÂÂ³Ã£ÂÂÃ£ÂÂÃ¦Â©ÂÃ¦Â¢Â°Ã§ÂÂÃ£ÂÂ«Ã§ÂµÂÃ£ÂÂ¿Ã§Â«ÂÃ£ÂÂ¦Ã£ÂÂÃ£ÂÂÃ©ÂÂÃ¥ÂÂ»Ã£ÂÂ®Ã¥ÂÂ¤Ã¥ÂÂÃ£ÂÂÃ¥ÂÂ¾Ã¥ÂÂÃ£ÂÂ«Ã¥ÂÂºÃ£ÂÂ¥Ã£ÂÂÃ¥ÂÂÃ¨ÂÂÃ¦ÂÂÃ¥Â Â±Ã£ÂÂ§Ã£ÂÂÃ£ÂÂÃ£ÂÂ
    Ã¤Â»ÂÃ¥Â¾ÂÃ£ÂÂ®Ã¦Â ÂªÃ¤Â¾Â¡Ã¥Â¤ÂÃ¥ÂÂÃ£ÂÂÃ¤Â¿ÂÃ¨Â¨Â¼Ã£ÂÂ»Ã¤ÂºÂÃ¦ÂÂ³Ã£ÂÂÃ£ÂÂÃ£ÂÂÃ£ÂÂ®Ã£ÂÂ§Ã£ÂÂ¯Ã£ÂÂªÃ£ÂÂÃ£ÂÂ"""
    t = tech_lookup.get(str(code).strip())
    if not t:
        return "Ã§ÂÂ´Ã¨Â¿ÂÃ£ÂÂ®Ã£ÂÂÃ£ÂÂ¯Ã£ÂÂÃ£ÂÂ«Ã£ÂÂ«Ã£ÂÂÃ£ÂÂ¼Ã£ÂÂ¿Ã£ÂÂ¯Ã¤Â»ÂÃ¥ÂÂÃ¥ÂÂÃ¥Â¾ÂÃ£ÂÂ§Ã£ÂÂÃ£ÂÂ¾Ã£ÂÂÃ£ÂÂÃ£ÂÂ§Ã£ÂÂÃ£ÂÂÃ£ÂÂÃ¥ÂÂ¤Ã¥ÂÂÃ£ÂÂÃ£ÂÂ¯Ã¥ÂÂÃ§Â¨Â®Ã¦Â ÂªÃ¤Â¾Â¡Ã¦ÂÂÃ¥Â Â±Ã£ÂÂµÃ£ÂÂ¼Ã£ÂÂÃ£ÂÂ¹Ã£ÂÂ§Ã£ÂÂÃ§Â¢ÂºÃ¨ÂªÂÃ£ÂÂÃ£ÂÂ Ã£ÂÂÃ£ÂÂÃ£ÂÂ"

    parts = []
    rsi = t.get("rsi")
    if isinstance(rsi, (int, float)):
        if rsi >= 70:
            parts.append(f"RSI(14)Ã£ÂÂ¯{rsi:.1f}Ã£ÂÂ§Ã¨Â²Â·Ã£ÂÂÃ£ÂÂÃ£ÂÂÃ£ÂÂÃ¦Â°Â´Ã¦ÂºÂÃ£ÂÂ«Ã£ÂÂÃ£ÂÂÃ£ÂÂÃ§ÂÂ­Ã¦ÂÂÃ§ÂÂÃ£ÂÂªÃ©ÂÂÃ§ÂÂ±Ã¦ÂÂÃ£ÂÂ«Ã§ÂÂÃ¦ÂÂ")
        elif rsi <= 30:
            parts.append(f"RSI(14)Ã£ÂÂ¯{rsi:.1f}Ã£ÂÂ§Ã¥Â£Â²Ã£ÂÂÃ£ÂÂÃ£ÂÂÃ£ÂÂÃ¦Â°Â´Ã¦ÂºÂ")
        else:
            parts.append(f"RSI(14)Ã£ÂÂ¯{rsi:.1f}Ã£ÂÂ§Ã¤Â¸Â­Ã§Â«ÂÃ¥ÂÂ")

    ma25 = t.get("ma25_dev")
    if ma25:
        parts.append(f"25Ã¦ÂÂ¥Ã§Â·ÂÃ£ÂÂÃ£ÂÂ{esc(ma25)}Ã¤Â¹ÂÃ©ÂÂ¢")

    signal = t.get("signal")
    if signal:
        parts.append(f"Ã£ÂÂ·Ã£ÂÂ°Ã£ÂÂÃ£ÂÂ«Ã¥ÂÂ¤Ã¥Â®ÂÃ£ÂÂ¯Ã£ÂÂ{esc(signal)}Ã£ÂÂ")

