# ---------------------------------------------------------------------------
# é®®åº¦ãã£ã«ã¿ã¼: å½æ¥ï¼å¹³æ¥ï¼ã¾ãã¯ç´åã®é±æ«åã®ã¿è¡¨ç¤º
# ---------------------------------------------------------------------------
def _freshness_cutoff(generated_at_str):
    """çææ¥ææå­å(YYYY-MM-DD HH:MM)ããè¡¨ç¤ºãã¹ãæå¤ã®æ¥ä»ãè¿ãã
    ææ: å+æ¥+æåãå«ããï¼ç´åã®åæããï¼
    åã»æ¥: é+å / å+æ¥ ãå«ãã
    ç«ãé: å½æ¥ã®ã¿"""
    from datetime import date as _d, datetime as _dt, timedelta as _td
    try:
        dt = _dt.strptime(generated_at_str[:10], "%Y-%m-%d").date()
    except Exception:
        return None
    wd = dt.weekday()  # 0=æ, 5=å, 6=æ¥
    if wd == 0:    return dt - _td(days=2)   # ææ: åã¾ã§é¡ã
    elif wd == 5:  return dt - _td(days=1)   # åæ: éã¾ã§é¡ã
    elif wd == 6:  return dt - _td(days=1)   # æ¥æ: åã¾ã§é¡ã
    else:          return dt                  # ç«ãé: å½æ¥ã®ã¿


def _parse_item_date(s, year):
    """'7/24' ã '7æ23æ¥(æ¨) 15:00' ãªã©ãã date ãåãåºããå¤±ææã¯ Noneã"""
    if not s:
        return None
    s = str(s)
    m = re.search(r"(\d{1,2})/(\d{1,2})", s)
    if m:
        try:
            from datetime import date as _d
            return _d(year, int(m.group(1)), int(m.group(2)))
        except ValueError:
            pass
    m = re.search(r"(\d{1,2})\u6708(\d{1,2})\u65e5", s)  # MæDæ¥
    if m:
        try:
            from datetime import date as _d
            return _d(year, int(m.group(1)), int(m.group(2)))
        except ValueError:
            pass
    return None


def _filter_by_freshness(items, date_key, generated_at_str):
    """date_key ãã£ã¼ã«ãã®æ¥ä»ã cutoff ä»¥éã®ã¢ã¤ãã ã®ã¿è¿ãã
    æ¥ä»è§£æã«å¤±æããã¢ã¤ãã ã¯ãã®ã¾ã¾å«ããã"""
    cutoff = _freshness_cutoff(generated_at_str)
    if cutoff is None:
        return list(items)
    year = int(generated_at_str[:4])
    return [it for it in items
            if _parse_item_date(it.get(date_key, ""), year) is None
            or _parse_item_date(it.get(date_key, ""), year) >= cutoff]


def _filter_tdnet_freshness(items, generated_at_str):
    """TDnet ã¢ã¤ãã ã® title æ«å°¾ã«åãè¾¼ã¾ããæ¥ä» ('MæDæ¥') ã§é®®åº¦ãã£ã«ã¿ã¼ã"""
    cutoff = _freshness_cutoff(generated_at_str)
    if cutoff is None:
        return list(items)
    year = int(generated_at_str[:4])
    return [it for it in items
            if _parse_item_date(it.get("title", ""), year) is None
            or _parse_item_date(it.get("title", ""), year) >= cutoff]


def build_html(data: dict) -> str:
    generated_at = data.get("generated_at", datetime.now().strftime("%Y-%m-%d %H:%M"))
    # é®®åº¦ãã£ã«ã¿ã¼: å½æ¥ä»¥åã®å¤ãå¥½ææã»æé·æ ªãã¼ã¿ãéè¡¨ç¤º
    fresh_us_good_news = _filter_by_freshness(data.get("us_good_news", []), "time", generated_at)
