    fut = data.get("nikkei_futures", {})

    idx_cards = ""
    for key, label in [("sp500", "S&P500"), ("dow", "NYÃ£ÂÂÃ£ÂÂ¦"), ("nasdaq", "Ã£ÂÂÃ£ÂÂ¹Ã£ÂÂÃ£ÂÂÃ£ÂÂ¯Ã§Â·ÂÃ¥ÂÂ"), ("sox", "SOXÃ¦ÂÂÃ¦ÂÂ°(Ã¥ÂÂÃ¥Â°ÂÃ¤Â½Â)")]:
        d = us.get(key, {})
        idx_cards += section_index_row(label, d.get("value", "Ã¢ÂÂ"), d.get("change_pct"), d.get("asof"))
    idx_cards += section_index_row("USD/JPY", fx.get("value", "Ã¢ÂÂ"), fx.get("change_pct"), fx.get("asof"))
    idx_cards += section_index_row("Ã¦ÂÂ¥Ã§ÂµÂ225Ã¥ÂÂÃ§ÂÂ©(CME/Ã¥Â¤Â§Ã©ÂÂª)", fut.get("value", "Ã¢ÂÂ"), fut.get("change_pct"), fut.get("asof"))
